// GENERATED by scripts/sync-engine.js from src/engine/met-norway.ts. Do not edit here; run `npm run sync-engine`.
/**
 * MET Norway Locationforecast 2.0 (fallback provider when Open-Meteo is down).
 * Free with attribution; requests MUST send an identifying User-Agent and use
 * coordinates with at most 4 decimals. Times come in UTC; we convert to Pakistan
 * time. Wind is m/s → km/h. There is no ET₀, so it's estimated with Hargreaves
 * (FAO-56 eq. 52) from daily max/min temperature and extraterrestrial radiation.
 * No past days → the irrigation balance shows "limited data" with this provider.
 */
import { FORECAST_SCHEMA_VERSION, PK_UTC_OFFSET, type Forecast, type Num } from './weather-rules.ts';

/** App name + public repo; no personal contact details. */
export const MET_USER_AGENT = 'KisanConnect/1.0 github.com/sajjadHunjra71/kisanconnect-farming-assistant-expo';

export function metNorwayUrl(lat: number, lng: number): string {
  const r = (v: number) => Math.round(v * 1e4) / 1e4;
  return `https://api.met.no/weatherapi/locationforecast/2.0/complete?lat=${r(lat)}&lon=${r(lng)}`;
}

/** Extraterrestrial radiation Ra (MJ m⁻² day⁻¹) for a latitude and day of year (FAO-56 eq. 21). */
export function extraterrestrialRadiation(latDeg: number, dayOfYear: number): number {
  const phi = (latDeg * Math.PI) / 180;
  const dr = 1 + 0.033 * Math.cos((2 * Math.PI * dayOfYear) / 365);
  const delta = 0.409 * Math.sin((2 * Math.PI * dayOfYear) / 365 - 1.39);
  const ws = Math.acos(Math.max(-1, Math.min(1, -Math.tan(phi) * Math.tan(delta))));
  return ((24 * 60) / Math.PI) * 0.082 * dr * (ws * Math.sin(phi) * Math.sin(delta) + Math.cos(phi) * Math.cos(delta) * Math.sin(ws));
}

/** Hargreaves ET₀ (mm/day). */
export function hargreavesEt0(tMax: number, tMin: number, latDeg: number, date: string): number {
  const doy = Math.floor((Date.parse(`${date}T00:00:00Z`) - Date.parse(`${date.slice(0, 4)}-01-01T00:00:00Z`)) / 86_400_000) + 1;
  const ra = extraterrestrialRadiation(latDeg, doy);
  const tMean = (tMax + tMin) / 2;
  const et0 = 0.0023 * (tMean + 17.8) * Math.sqrt(Math.max(0, tMax - tMin)) * ra * 0.408;
  return Math.round(et0 * 10) / 10;
}

/** MET symbol code → WMO-like code used by conditionFromCode. */
export function symbolToCode(symbol: string | undefined): Num {
  if (!symbol) return null;
  const s = symbol.replace(/_(day|night|polartwilight)$/, '');
  if (s.includes('thunder')) return 95;
  if (s.includes('snow') || s.includes('sleet')) return 71;
  if (s.startsWith('heavyrain')) return 65;
  if (s.startsWith('lightrain')) return 51;
  if (s.includes('rainshowers')) return 80;
  if (s.includes('rain')) return 61;
  if (s === 'fog') return 45;
  if (s === 'cloudy') return 3;
  if (s === 'partlycloudy' || s === 'fair') return s === 'fair' ? 1 : 2;
  if (s === 'clearsky') return 0;
  return null;
}

type Entry = {
  time: string;
  data: {
    instant: { details: Record<string, number | undefined> };
    next_1_hours?: { summary?: { symbol_code?: string }; details?: Record<string, number | undefined> };
    next_6_hours?: { summary?: { symbol_code?: string }; details?: Record<string, number | undefined> };
  };
};

const kmh = (ms: number | undefined): Num => (typeof ms === 'number' ? Math.round(ms * 3.6 * 10) / 10 : null);
const numOrNull = (x: number | undefined): Num => (typeof x === 'number' && Number.isFinite(x) ? x : null);

export function parseMetNorway(body: unknown, fetchedAt: string): Forecast {
  const b = body as { geometry?: { coordinates?: number[] }; properties?: { timeseries?: Entry[] } };
  const ts = b?.properties?.timeseries;
  if (!Array.isArray(ts) || ts.length === 0) throw new Error('met-norway: no data');
  const [lng, lat] = b.geometry?.coordinates ?? [0, 0];
  const local = (utc: string) => new Date(Date.parse(utc) + PK_UTC_OFFSET * 1000).toISOString().slice(0, 13) + ':00';

  // Hourly series: only the consecutive hourly part (entries with next_1_hours).
  const hourly: Forecast['hourly'] = { time: [], tempC: [], feelsLikeC: [], humidity: [], precipMm: [], rainProb: [], windKmh: [], gustKmh: [], visibilityM: [], code: [] };
  for (const e of ts) {
    if (!e.data.next_1_hours) break;
    const i = e.data.instant.details;
    const n1 = e.data.next_1_hours;
    hourly.time.push(local(e.time));
    hourly.tempC.push(numOrNull(i.air_temperature));
    hourly.feelsLikeC.push(null);
    hourly.humidity.push(numOrNull(i.relative_humidity));
    hourly.precipMm.push(numOrNull(n1.details?.precipitation_amount));
    hourly.rainProb.push(numOrNull(n1.details?.probability_of_precipitation));
    hourly.windKmh.push(kmh(i.wind_speed));
    hourly.gustKmh.push(kmh(i.wind_speed_of_gust));
    hourly.visibilityM.push(null);
    hourly.code.push(symbolToCode(n1.summary?.symbol_code));
  }

  // Daily: from every entry (hourly then 6-hourly), grouped by local date.
  const days = new Map<string, { temps: number[]; precip: number; precipKnown: boolean; symbols: string[] }>();
  ts.forEach((e, k) => {
    const date = local(e.time).slice(0, 10);
    const day = days.get(date) ?? { temps: [], precip: 0, precipKnown: false, symbols: [] };
    const t = e.data.instant.details.air_temperature;
    if (typeof t === 'number') day.temps.push(t);
    // Count each hour once: next_1_hours where hourly data exists, otherwise next_6_hours.
    const p1 = e.data.next_1_hours?.details?.precipitation_amount;
    const p6 = e.data.next_6_hours?.details?.precipitation_amount;
    const hourlyPart = !!e.data.next_1_hours && (k === 0 || !!ts[k - 1].data.next_1_hours);
    if (hourlyPart && typeof p1 === 'number') {
      day.precip += p1;
      day.precipKnown = true;
    } else if (!e.data.next_1_hours && typeof p6 === 'number') {
      day.precip += p6;
      day.precipKnown = true;
    }
    const sym = e.data.next_1_hours?.summary?.symbol_code ?? e.data.next_6_hours?.summary?.symbol_code;
    if (sym) day.symbols.push(sym);
    days.set(date, day);
  });

  const daily: Forecast['daily'] = { date: [], maxC: [], minC: [], precipMm: [], et0Mm: [], code: [] };
  for (const [date, day] of days) {
    // A day needs enough readings to trust its max/min (skip the partial first/last day).
    const enough = day.temps.length >= 4;
    const max = enough ? Math.max(...day.temps) : null;
    const min = enough ? Math.min(...day.temps) : null;
    daily.date.push(date);
    daily.maxC.push(max);
    daily.minC.push(min);
    daily.precipMm.push(day.precipKnown ? Math.round(day.precip * 10) / 10 : null);
    daily.et0Mm.push(max !== null && min !== null ? hargreavesEt0(max, min, lat, date) : null);
    const codes = day.symbols.map(symbolToCode).filter((c): c is number => c !== null);
    daily.code.push(codes.length ? Math.max(...codes) : null);
  }

  return { provider: 'met-norway', schemaVersion: FORECAST_SCHEMA_VERSION, lat, lng, utcOffsetSeconds: PK_UTC_OFFSET, fetchedAt, hourly, daily };
}
